enum {
     cached_info(25), (65535)
} ExtensionType;

enum {
     cert(1), cert_req(2) (255)
} CachedInformationType;

struct {
     select (type) {
       case client:
         CachedInformationType type;
         opaque hash_value<1..255>;
       case server:
         CachedInformationType type;
       } body;
} CachedObject;
